create table RB_APPR_LETTER_SUB (APPR_LETTER_NO VARCHAR(50) not null  ,MAIN_SUB_IND VARCHAR(1) not null  ,CCY VARCHAR(3) not null  ,APPR_LIMIT_AMT DECIMAL(17,2) null  ,CR_TOTAL_AMT DECIMAL(38,2) null  ,DR_TOTAL_AMT DECIMAL(17,2) null  ,GRACE_AMT DECIMAL(17,2) null  ,GRACE_PROPORTION DECIMAL(5,2) null  ,CLIENT_NO VARCHAR(22) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,REMARK VARCHAR(200) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(APPR_LETTER_NO,MAIN_SUB_IND,CCY,CLIENT_NO));